import{_ as t,o,c as n,a0 as i}from"./chunks/framework.CShDTZbC.js";const h=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"DevFix","text":"Autonomous Environment Recovery","tagline":"The open-source AI agent that detects, diagnoses, and fixes broken local development environments.","actions":[{"theme":"brand","text":"Quick Start","link":"/quickstart"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/ghulam-mustafa/devfix"}]},"features":[{"title":"Self-Verifying Fixes","details":"Doesn't just guess. It actively runs your tests (like npm run build) to mathematically prove the environment is fixed."},{"title":"Secure & Sandboxed","details":"AI shell access is dangerous. DevFix isolates all actions inside a secure Docker container, protecting your laptop."},{"title":"Language Agnostic","details":"Automatically detects and supports Node.js, TypeScript, and Python without complex configuration."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),a={name:"index.md"};function s(r,e,l,c,u,d){return o(),n("div",null,[...e[0]||(e[0]=[i('<h2 id="the-it-works-on-my-machine-solver" tabindex="-1">The &quot;It Works on My Machine&quot; Solver <a class="header-anchor" href="#the-it-works-on-my-machine-solver" aria-label="Permalink to &quot;The &quot;It Works on My Machine&quot; Solver&quot;">​</a></h2><p>DevFix is an AI-powered CLI tool designed to solve the headache of broken local environments.</p><p>When a project refuses to build, dependencies conflict, or native binaries are missing, you shouldn&#39;t have to spend hours Googling cryptic stack traces. You simply run <code>devfix inspect .</code>, and the agent will:</p><ol><li><strong>Observe:</strong> Inspect configurations, package managers, and runtimes without executing code.</li><li><strong>Execute:</strong> Spin up a secure Docker sandbox and attempt to build the project.</li><li><strong>Diagnose:</strong> Analyze stack traces and missing dependencies deeply.</li><li><strong>Fix:</strong> Interactively patch code, install missing packages, and re-run until the environment is healthy.</li></ol><h2 id="open-source-evolving" tabindex="-1">Open Source &amp; Evolving <a class="header-anchor" href="#open-source-evolving" aria-label="Permalink to &quot;Open Source &amp; Evolving&quot;">​</a></h2><p>DevFix started as an experiment to see if LLMs could reliably troubleshoot broken configurations without human intervention. We succeeded in building a framework that achieves high recovery rates on severely broken projects.</p><p>Today, DevFix is evolving into a serious, everyday developer tool.</p><p>We are actively designing a VS Code Extension, adding support for Rust and Go, and building custom verifier integrations. <strong>We are looking for contributors!</strong> Check out our Roadmap and jump into our GitHub repository to submit your first Pull Request.</p>',8)])])}const g=t(a,[["render",s]]);export{h as __pageData,g as default};
